//! HashV1 / DigestRef conformance: consumes the FROZEN corpus under
//! `spec/conformance/digest/` and the frozen domain table
//! `spec/tables/hash-domains.json`.
//!
//! Expected digest values were generated by an independent implementation
//! (Python `hashlib`) and are physically frozen. Tests never re-derive them
//! from the implementation under test.

use af_core::{DigestAlgorithm, DigestDomain, DigestError, DigestRef, hash_v1};
use serde::Deserialize;
use std::collections::HashSet;
use std::path::{Path, PathBuf};

fn spec_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../spec")
}

fn load_json(relative: &str) -> serde_json::Value {
    let path = spec_dir().join(relative);
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("cannot parse {}: {e}", path.display()))
}

#[derive(Deserialize)]
struct HashGolden {
    #[allow(dead_code)]
    kind: String,
    corpus_revision: u64,
    cases: Vec<HashCase>,
}

#[derive(Deserialize)]
struct HashCase {
    case_id: String,
    domain: String,
    payload_hex: String,
    expected_sha256_hex: String,
}

#[test]
fn hash_v1_golden() {
    let file: HashGolden =
        serde_json::from_value(load_json("conformance/digest/hash-v1-golden.json"))
            .expect("hash-v1-golden.json is valid");
    assert_eq!(file.corpus_revision, 2, "unexpected corpus revision");
    assert!(
        file.cases.len() >= 10,
        "golden digest corpus must be non-trivial"
    );

    for case in &file.cases {
        let domain = DigestDomain::from_registry_name(&case.domain)
            .unwrap_or_else(|e| panic!("case {}: {e}", case.case_id));
        let payload = hex::decode(&case.payload_hex).expect("fixture payload is hex");

        let digest = hash_v1(domain, &payload);
        assert_eq!(
            hex::encode(digest),
            case.expected_sha256_hex,
            "case {}: HashV1 digest mismatch",
            case.case_id
        );

        // DigestRef must carry the same identity without losing the domain.
        let digest_ref = DigestRef::compute(domain, &payload);
        assert_eq!(digest_ref.alg(), DigestAlgorithm::Sha256);
        assert_eq!(digest_ref.domain(), domain);
        assert_eq!(digest_ref.hex(), case.expected_sha256_hex);
        assert_eq!(digest_ref.hex().len(), 64);

        // Determinism.
        assert_eq!(
            hash_v1(domain, &payload),
            digest,
            "case {}: not deterministic",
            case.case_id
        );
    }
}

#[derive(Deserialize)]
struct DomainSeparation {
    #[allow(dead_code)]
    kind: String,
    corpus_revision: u64,
    payload_hex: String,
    domains: Vec<DomainEntry>,
}

#[derive(Deserialize)]
struct DomainEntry {
    domain: String,
    expected_sha256_hex: String,
}

#[test]
fn domain_separation() {
    let fixture: DomainSeparation =
        serde_json::from_value(load_json("conformance/digest/domain-separation.json"))
            .expect("domain-separation.json is valid");
    assert_eq!(fixture.corpus_revision, 2, "unexpected corpus revision");
    let payload = hex::decode(&fixture.payload_hex).expect("fixture payload is hex");

    let mut seen = HashSet::new();
    for entry in &fixture.domains {
        let domain = DigestDomain::from_registry_name(&entry.domain)
            .unwrap_or_else(|e| panic!("domain {}: {e}", entry.domain));
        let digest = hash_v1(domain, &payload);
        assert_eq!(
            hex::encode(digest),
            entry.expected_sha256_hex,
            "domain {}: digest mismatch",
            entry.domain
        );
        assert!(
            seen.insert(hex::encode(digest)),
            "domain {}: digest collision — domain separation broken",
            entry.domain
        );
    }
    assert_eq!(
        seen.len(),
        DigestDomain::ALL.len(),
        "every registered domain must appear in the fixture"
    );
}

/// Same payload under every domain — proven distinct without any fixture, as a
/// direct property test on top of the frozen one.
#[test]
fn domain_separation_property() {
    let payload = b"property-probe-payload";
    let mut seen = HashSet::new();
    for domain in DigestDomain::ALL {
        assert!(seen.insert(hex::encode(hash_v1(*domain, payload))));
    }
    assert_eq!(seen.len(), DigestDomain::ALL.len());
}

/// The frozen `spec/tables/hash-domains.json` and the `DigestDomain` enum must
/// never drift apart.
#[test]
fn hash_domains_table_matches_registry_enum() {
    let table = load_json("tables/hash-domains.json");
    let table_domains: Vec<&str> = table["domains"]
        .as_array()
        .expect("domains array")
        .iter()
        .map(|d| d["domain"].as_str().expect("domain string"))
        .collect();

    let enum_domains: Vec<&str> = DigestDomain::ALL.iter().map(DigestDomain::as_str).collect();
    assert_eq!(
        table_domains, enum_domains,
        "hash-domains.json and DigestDomain::ALL have drifted apart"
    );
    assert_eq!(
        table["hash_algorithm"].as_str(),
        Some("sha256"),
        "v1 freezes sha256"
    );
    assert_eq!(table["prefix_ascii"].as_str(), Some("AF"));
}

/// `machine-primitives.afidl` must mention every machine primitive the crate
/// implements (lightweight drift check; the full AFIDL grammar is a later
/// phase).
#[test]
fn machine_primitives_afidl_matches_implemented_set() {
    let path = spec_dir().join("../spec/idl/core/machine-primitives.afidl");
    let path = if path.exists() {
        path
    } else {
        spec_dir()
            .parent()
            .unwrap()
            .join("spec/idl/core/machine-primitives.afidl")
    };
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    for primitive in [
        "unit",
        "null",
        "bool",
        "int32",
        "uint32",
        "int64",
        "uint64",
        "decimal",
        "float64",
        "string",
        "bytes",
        "timestamp",
        "duration",
    ] {
        assert!(
            text.contains(primitive),
            "machine-primitives.afidl is missing primitive {primitive:?}"
        );
    }
}

#[derive(Deserialize)]
struct DigestNegativeFile {
    #[allow(dead_code)]
    kind: String,
    corpus_revision: u64,
    cases: Vec<DigestNegativeCase>,
}

#[derive(Deserialize)]
struct DigestNegativeCase {
    case_id: String,
    #[allow(dead_code)]
    description: String,
    input: String,
    error_class: String,
}

#[test]
fn digest_negatives() {
    let file: DigestNegativeFile =
        serde_json::from_value(load_json("conformance/digest/negative.json"))
            .expect("digest negative.json is valid");
    assert_eq!(file.corpus_revision, 2, "unexpected corpus revision");
    assert!(file.cases.len() >= 5);

    for case in &file.cases {
        match DigestRef::from_display(&case.input) {
            Err(e) => assert_eq!(
                e.kind(),
                case.error_class,
                "case {}: digest error kind mismatch ({e})",
                case.case_id
            ),
            Ok(digest) => panic!(
                "case {}: expected error {} but parsed {digest}",
                case.case_id, case.error_class
            ),
        }
    }
}

/// DigestRef strictness beyond the frozen corpus.
#[test]
fn digest_ref_strictness() {
    let computed = DigestRef::compute(DigestDomain::Conformance, b"probe");
    let hex = computed.hex();

    // Lowercase, fixed length, round-trips through the convenience form.
    assert!(
        hex.chars()
            .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase())
    );
    let reparsed = DigestRef::from_display(&computed.to_string()).unwrap();
    assert_eq!(reparsed, computed);
    assert_eq!(reparsed.raw_bytes().len(), 32);

    // Unknown domains never resolve.
    assert!(matches!(
        DigestDomain::from_registry_name("Semantic-IR"), // case-sensitive registry
        Err(DigestError::UnknownDigestDomain { .. })
    ));
}
